reference_solution:
def h_index(citations):
    size = len(citations)
    buckets = [0] * (size + 1)
    for citation in citations:
        buckets[min(citation, size)] += 1
    papers = 0
    for candidate in range(size, -1, -1):
        papers += buckets[candidate]
        if papers >= candidate:
            return candidate

